The isolated pixels must be filled with the surrounding shape's color, not the background. I'll fill singletons with the most common neighboring non-background color.

```python
from collections import Counter

def transform(grid):
    R, C = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    seen = [[False]*C for _ in range(R)]
    out = [row[:] for row in grid]
    for i in range(R):
        for j in range(C):
            if grid[i][j] != bg and not seen[i][j]:
                stack = [(i,j)]
                seen[i][j] = True
                comp = []
                while stack:
                    x,y = stack.pop()
                    comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny = x+dx,y+dy
                        if 0<=nx<R and 0<=ny<C and not seen[nx][ny] and grid[nx][ny]==grid[i][j]:
                            seen[nx][ny]=True
                            stack.append((nx,ny))
                if len(comp) < 2:
                    x,y = comp[0]
                    neigh = []
                    for dx in (-1,0,1):
                        for dy in (-1,0,1):
                            if dx==0 and dy==0: continue
                            nx,ny = x+dx,y+dy
                            if 0<=nx<R and 0<=ny<C and grid[nx][ny]!=grid[x][y]:
                                neigh.append(grid[nx][ny])
                    if neigh:
                        out[x][y] = Counter(neigh).most_common(1)[0][0]
                    else:
                        out[x][y] = bg
    return out
